CREATE TABLE IF NOT EXISTS users(id BIGINT PRIMARY KEY,name TEXT NOT NULL,chat_id BIGINT,created TEXT NOT NULL,reports INTEGER NOT NULL DEFAULT 1,reminders INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS debts(id SERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),title TEXT NOT NULL,person TEXT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),date TEXT NOT NULL,due_date TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN ('lent','borrowed')),paid INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS debts_user ON debts(user_id);
CREATE TABLE IF NOT EXISTS expenses(id SERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),title TEXT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),date TEXT NOT NULL,category TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS expenses_user_date ON expenses(user_id,date);
CREATE TABLE IF NOT EXISTS outbox(key TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,text TEXT NOT NULL,sent INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,next_at BIGINT NOT NULL DEFAULT 0,ref_id INTEGER,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(sent,next_at);
CREATE TABLE IF NOT EXISTS state(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_updates(id BIGINT PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits(user_id BIGINT PRIMARY KEY,bucket BIGINT NOT NULL,count INTEGER NOT NULL DEFAULT 1);
